from pathlib import Path
from PIL import Image
import json,hashlib,subprocess
P=Path(__file__).resolve().parent;ROOT=P.parents[5];model=Image.open(ROOT/'assets/characters/thomas/rig/production/model-s.png').convert('RGBA');palette={c[:3] for c in model.get_flattened_data() if c[3]};records=[]
for n in (1,3,5,7):
 im=Image.open(P/f'key-{n:02d}-1x.png').convert('RGBA');g=Image.open(P/f'guide-{n:02d}-4x.png').resize((80,80),Image.Resampling.NEAREST).convert('RGBA');assert im.size==(80,80);assert set(im.getchannel('A').get_flattened_data())=={0,255};assert all(c[:3] in palette for c in im.get_flattened_data() if c[3]);assert im.crop((0,0,80,32)).tobytes()==g.crop((0,0,80,32)).tobytes();assert im.crop((0,67,80,80)).tobytes()==g.crop((0,67,80,80)).tobytes()
 mask=lambda img:{(x,y) for y in range(80) for x in range(80) if img.getpixel((x,y))[3]};a=mask(im);b=mask(g);near=lambda p,m:any((p[0]+dx,p[1]+dy) in m for dx in (-1,0,1) for dy in (-1,0,1));assert all(near(p,b) for p in a);assert all(near(p,a) for p in b)
 records.append({'frame':n,'size':[80,80],'palette':'approved model only','outline_iou':len(a&b)/len(a|b),'guide_envelope_pixels':1,'head_and_boot_regions':'exact guide pixels','sha256':hashlib.sha256((P/f'key-{n:02d}-1x.png').read_bytes()).hexdigest()})
protected=['assets/characters/thomas/rig/production/model-s.png','assets/characters/thomas/rig/production/model-s_n.png','assets/characters/thomas/rig/s.png','assets/characters/thomas/rig/s_n.png','assets/characters/thomas/production/sprites/standing-candidate.png','assets/characters/thomas/production/sprites/steady-portrait-candidate.png']
for path in protected:assert (ROOT/path).read_bytes()==subprocess.check_output(['git','show','origin/main:'+path],cwd=ROOT)
check=json.loads((P/'guide-check.json').read_text());assert check['keys_pass'];(P/'validation.json').write_text(json.dumps({'job':'15-W step A','status':('APPROVED BY JULIAN 2026-11-01' if (P.parent/'15w-step-b/approval.json').exists() else 'PENDING JULIAN APPROVAL'),'frames':records,'protected_files_unchanged':protected,'upstream_prompt_sha256':hashlib.sha256((ROOT/'design/art-briefs/animation/walk-s/PROMPT.md').read_bytes()).hexdigest(),'runtime_sheet_delivered':False,'in_between_frames_painted':False,'normal_maps_painted':False,'checker':check},indent=2)+'\n');print(json.dumps({'keys':[r['frame'] for r in records],'outline_iou':[round(r['outline_iou'],3) for r in records],'guide_envelope':'within1px both ways','head_and_boots':'unchanged','approval':('approved; see ../15w-step-b/approval.json' if (P.parent/'15w-step-b/approval.json').exists() else 'pending')}))
